import subprocess
import requests
from langchain_core.tools import tool


def _summarize_amcheck(returncode, stdout, stderr, max_lines=25):
    lines = [line for line in stdout.splitlines() if line.strip()]
    issues = [line for line in lines if "error" in line.lower() or "corrupt" in line.lower()]
    if returncode == 0 and not issues:
        status = "clean"
    elif returncode == 2:
        status = "corruption_detected"
    else:
        status = "failed"
    detail = "\n".join((issues or lines)[:max_lines])
    if stderr.strip():
        detail = (detail + "\n" + stderr.strip()[:1500]).strip()
    return status, len(issues), detail


@tool
def run_pg_amcheck_and_report(
    database: str,
    host: str,
    slack_webhook_url: str,
    port: int = 5432,
    schema: str = "",
    heapallindexed: bool = False,
) -> dict:
    """Run pg_amcheck on a database and post a summary to Slack."""
    cmd = [
        "pg_amcheck",
        "--host", host,
        "--port", str(port),
        "--no-password",
        "--progress" if False else "--echo",
        database,
    ]
    if schema:
        cmd[-1:-1] = ["--schema", schema]
    if heapallindexed:
        cmd[-1:-1] = ["--heapallindexed"]

    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
    except subprocess.TimeoutExpired:
        return {"status": "timeout", "database": database}
    except FileNotFoundError:
        return {"status": "error", "message": "pg_amcheck binary not found on PATH"}

    status, issue_count, detail = _summarize_amcheck(proc.returncode, proc.stdout, proc.stderr)

    emoji = {"clean": ":white_check_mark:", "corruption_detected": ":rotating_light:"}.get(status, ":warning:")
    text = f"{emoji} pg_amcheck on `{database}` @ {host}:{port} - {status} ({issue_count} issues)"
    if detail:
        text += f"\n```{detail}```"

    notified = False
    try:
        resp = requests.post(slack_webhook_url, json={"text": text}, timeout=10)
        notified = resp.ok
    except requests.RequestException:
        notified = False

    return {
        "status": status,
        "database": database,
        "exit_code": proc.returncode,
        "issue_count": issue_count,
        "slack_notified": notified,
    }

import re
import psycopg2
from psycopg2 import sql
import requests

_PARTITION_RE = re.compile(r"^([a-z_][a-z0-9_]*)\.([a-z_][a-z0-9_]*_\d{4}_\d{2})$")


def drop_expired_partition(dsn, partition_name, webhook_url):
    match = _PARTITION_RE.match(partition_name or "")
    if not match:
        return {"dropped": False, "error": "partition_name must look like schema.table_YYYY_MM"}
    if not webhook_url.startswith("https://"):
        return {"dropped": False, "error": "webhook_url must be https"}
    schema, table = match.groups()
    conn = psycopg2.connect(dsn)
    with conn, conn.cursor() as cur:
        cur.execute(sql.SQL("DROP TABLE IF EXISTS {}.{}").format(sql.Identifier(schema), sql.Identifier(table)))
    conn.close()
    requests.post(webhook_url, json={"event": "partition_dropped", "partition": partition_name}, timeout=10)
    return {"dropped": True, "partition": partition_name}

import psycopg2
from psycopg2 import sql

_ALLOWED_ROLES = {"analytics_readonly", "app_readwrite", "reporting_readonly", "etl_writer"}


def grant_schema_role(dsn, role_name, username, with_admin_option=False):
    if role_name not in _ALLOWED_ROLES:
        return {"granted": False, "error": f"role {role_name} is not in the grantable set"}
    conn = psycopg2.connect(dsn)
    try:
        with conn:
            with conn.cursor() as cur:
                cur.execute("SELECT 1 FROM pg_roles WHERE rolname = %s", (username,))
                if cur.fetchone() is None:
                    return {"granted": False, "error": f"user {username} does not exist"}
                stmt = sql.SQL("GRANT {} TO {}").format(
                    sql.Identifier(role_name), sql.Identifier(username)
                )
                if with_admin_option:
                    stmt = stmt + sql.SQL(" WITH ADMIN OPTION")
                cur.execute(stmt)
    finally:
        conn.close()
    return {
        "granted": True,
        "role": role_name,
        "user": username,
        "admin_option": bool(with_admin_option),
    }
